        </div>
        <nav className="sidebar-nav">
          <div className="nav-section-label">Navigation</div>
          {config.navItems.map(item => (
            <a key={item.label} className={`nav-item ${item.active ? 'active' : ''}`} href="#">
              <span className="nav-icon">{item.icon}</span>
