      </aside>

      {/* Main Content */}
      <div className="main-content">
        {/* Topbar */}
        <header className="topbar">
          <div className="topbar-left">
            <h1>{config.title}</h1>
            <div className="live-badge">
              <div className="live-dot"></div>
              LIVE
            </div>
          </div>
          <div className="topbar-right">
            <span className="topbar-time">{time}</span>
            <button className="topbar-btn" title="Notifications">≡ƒöö<span className="notif-dot"></span></button>
            <button className="topbar-btn" title="Settings">ΓÜÖ∩╕Å</button>
          </div>
        </header>

        {/* Dashboard Body */}
        <div className="dashboard-body">
          {/* Metrics Row */}
          <div className="metrics-row">
            {metrics.map(m => (
              <div key={m.label} className="metric-card">
                <div className="metric-icon">{m.icon}</div>
                <div className="metric-label">{m.label}</div>
                <div className="metric-value">{m.value}</div>
                <div className="metric-subtext">{m.subtext}</div>
                <div className={`metric-trend ${m.trend}`}>{m.trend === 'up' ? 'Γåæ' : m.trend === 'down' ? 'Γåô' : 'ΓåÆ'} {m.trendText}</div>
              </div>
            ))}
          </div>

          {/* Main Grid */}
          <div className="main-grid">
            {/* Map Panel */}
            <div className="panel map-panel">
              <div className="panel-header">
                <h3>{mapMeta.title}</h3>
                <span className="panel-badge">{mapMeta.badge}</span>
              </div>
              <div className="panel-body">
                <div className="map-container">
                  <div className="map-grid"></div>
                  {baseConfig.markers.map(m => (
                    <div key={m.label} className="map-marker" style={{ top: m.top, left: m.left }}>
                      <div className={`marker-dot ${m.type}`}>{m.icon}</div>
                      <span className="marker-label">{m.label}</span>
                    </div>
                  ))}
                  <div className="map-legend">
                    {baseConfig.legend.map(l => (
                      <div key={l.label} className="legend-item">
                        <div className="legend-dot" style={{ background: l.color }}></div>
                        {l.label}
                      </div>
                    ))}
                  </div>
                </div>
              </div>
            </div>

            {/* Alerts Panel */}
            <div className="panel alerts-panel">
              <div className="panel-header">
                <h3>Alerts & Activity</h3>
                <span className="panel-badge">{alerts.length} Active</span>
              </div>
              <div className="panel-body">
                {alerts.map((a, i) => (
                  <div key={i} className={`alert-item ${a.type}`}>
                    <div className="alert-title">{a.title}</div>
