import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { Auth } from '../services/auth';
import { apiFetch } from '../services/api';
import '../css/styles.css';

const PatientPortalPage = () => {
  const navigate = useNavigate();
  const user = Auth.user;
  const [activeTab, setActiveTab] = useState('overview');
  const [searchQuery, setSearchQuery] = useState('');
  const [hospitals, setHospitals] = useState([]);
  const [loading, setLoading] = useState(false);
  const [appointments, setAppointments] = useState([]);
  const [bedSummaries, setBedSummaries] = useState({});

  useEffect(() => {
    if (!user) { navigate('/signin'); return; }
    fetchHospitals();
    fetchAppointments();
  }, []);

  const fetchHospitals = async () => {
    setLoading(true);
    try {
      // Public hospital search endpoint ΓÇö city-level search for patient portal
      const res = await apiFetch('/api/hospitals/search/?city=Bhopal');
      if (res.ok) {
        const data = await res.json();
        const list = Array.isArray(data) ? data : data.results || [];
        setHospitals(list);

        // Fetch cached bed availability per hospital (Redis, 2 min TTL)
        const summaries = {};
        await Promise.all(
          list.map(async (hosp) => {
            if (!hosp.id) return;
            try {
              const bedRes = await apiFetch(`/api/beds/availability/${hosp.id}/`);
              if (bedRes.ok) {
                const summary = await bedRes.json();
                summaries[hosp.id] = summary;
              }
            } catch {
              // ignore per-hospital errors; fallback UI will show total_beds
            }
          })
        );
        setBedSummaries(summaries);
      } else {
        // graceful fallback to static sample data
        setHospitals([
          { id: 1, name: 'St. Jude Medical Center', category: 'Private', city: 'Bhopal', total_beds: 150 },
          { id: 2, name: 'Metro General Hospital', category: 'Government', city: 'Bhopal', total_beds: 300 },
          { id: 3, name: 'City Hospital', category: 'Private', city: 'Bhopal', total_beds: 200 },
        ]);
      }
    } catch (e) {
      setHospitals([
        { id: 1, name: 'St. Jude Medical Center', category: 'Private', city: 'Bhopal', total_beds: 150 },
        { id: 2, name: 'Metro General Hospital', category: 'Government', city: 'Bhopal', total_beds: 300 },
        { id: 3, name: 'City Hospital', category: 'Private', city: 'Bhopal', total_beds: 200 },
      ]);
    }
    setLoading(false);
  };

  const fetchAppointments = async () => {
    try {
      const res = await apiFetch('/api/appointments/');
      if (res.ok) { const data = await res.json(); setAppointments(Array.isArray(data) ? data : data.results || []); }
    } catch (e) {
      setAppointments([
        { id: 1, hospital: 'St. Jude Medical', doctor: 'Dr. Arjun Varma', date: '2026-03-20', time: '10:30 AM', status: 'Confirmed' },
        { id: 2, hospital: 'City Hospital', doctor: 'Dr. Sara Khan', date: '2026-03-22', time: '2:00 PM', status: 'Pending' },
      ]);
    }
  };

  const handleLogout = async () => { await Auth.logout(); navigate('/'); };

  const filteredHospitals = hospitals.filter(h => h.name?.toLowerCase().includes(searchQuery.toLowerCase()));

  const getBedSnapshot = (hospital) => {
    const summary = bedSummaries[hospital.id];
    if (!summary) {
      return {
        availableBeds: hospital.available_beds || 0,
        icuBeds: hospital.icu_capacity || 0,
      };
    }
    const byType = summary.by_type || {};
    const icu = byType.icu || byType.ICU || {};
    return {
      availableBeds: summary.available_beds || 0,
      icuBeds: icu.available || 0,
    };
  };

  const navTabs = [
    { id: 'overview', label: 'Overview', icon: '≡ƒÅá' },
    { id: 'search', label: 'Find Hospital', icon: '≡ƒöì' },
    { id: 'appointments', label: 'Appointments', icon: '≡ƒôà' },
    { id: 'records', label: 'My Records', icon: '≡ƒôï' },
  ];

  return (
    <div style={{ fontFamily: 'Inter, sans-serif', backgroundColor: '#FDFCF7', minHeight: '100vh' }}>
      <style>{`
        .hero-heading { font-family: 'Playfair Display', serif; }
        .patient-nav { position: fixed; top: 0; left: 0; right: 0; z-index: 50; background: rgba(253,252,247,0.9); backdrop-filter: blur(16px); border-bottom: 1px solid rgba(27,67,50,0.05); padding: 16px 40px; display: flex; align-items: center; justify-content: space-between; }
        .tab-btn { padding: 10px 20px; border-radius: 20px; font-size: 13px; font-weight: 600; cursor: pointer; border: none; background: transparent; color: #64748b; transition: all 0.2s; display: flex; align-items: center; gap: 8px; }
        .tab-btn.active { background: #1B4332; color: white; }
        .tab-btn:hover:not(.active) { background: #f0fdf4; color: #1B4332; }
        .hosp-card { background: white; border-radius: 24px; padding: 24px; border: 1px solid #e5e7eb; transition: all 0.3s; }
        .hosp-card:hover { box-shadow: 0 12px 30px -8px rgba(27,67,50,0.12); transform: translateY(-4px); }
      `}</style>

      {/* Top Nav */}
      <nav className="patient-nav">
        <div className="flex items-center gap-3">
          <div className="w-8 h-8 bg-[#1B4332] rounded-xl flex items-center justify-center"><span className="text-white font-bold text-sm">+</span></div>
          <span className="text-lg font-black text-[#1B4332]">MedGrid</span>
        </div>
        <div className="flex gap-1">
          {navTabs.map(tab => (
            <button key={tab.id} className={`tab-btn ${activeTab === tab.id ? 'active' : ''}`} onClick={() => setActiveTab(tab.id)}>
              {tab.icon} {tab.label}
            </button>
          ))}
        </div>
        <div className="flex items-center gap-4">
          <div className="flex items-center gap-2 px-4 py-2 bg-green-50 rounded-full">
            <div className="w-7 h-7 bg-[#1B4332] rounded-full flex items-center justify-center text-white text-[10px] font-black">
              {(user?.name || 'P')[0]}
            </div>
            <span className="text-sm font-bold text-[#1B4332]">{user?.name || 'Patient'}</span>
          </div>
          <button onClick={handleLogout} className="text-sm font-bold text-red-500 hover:bg-red-50 px-4 py-2 rounded-full transition-all">Sign Out</button>
        </div>
      </nav>

      <div className="pt-24 px-10 pb-10">
        {/* Overview */}
        {activeTab === 'overview' && (
          <div className="max-w-5xl mx-auto space-y-10">
            <div className="py-8">
              <h1 className="text-5xl font-black text-[#1B4332] hero-heading italic mb-3">Welcome back, {user?.name?.split(' ')[0] || 'Patient'}.</h1>
              <p className="text-gray-500 text-lg font-medium">Your health grid is active and monitoring.</p>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
              {[
                { label: 'Next Appointment', value: appointments[0]?.date || 'None scheduled', icon: '≡ƒôà', color: '#dcfce7', textColor: '#16a34a' },
                { label: 'Nearby Hospitals', value: `${hospitals.filter(h => (h.available_beds || 0) > 0).length || 3} Available`, icon: '≡ƒÅÑ', color: '#eff6ff', textColor: '#3b82f6' },
                { label: 'Health Status', value: 'Active & Monitored', icon: 'Γ¥ñ∩╕Å', color: '#fdf2f8', textColor: '#ec4899' },
              ].map(card => (
                <div key={card.label} className="bg-white rounded-3xl p-8 border border-gray-100 shadow-sm">
                  <div className="w-12 h-12 rounded-2xl flex items-center justify-center text-2xl mb-4" style={{ background: card.color }}>{card.icon}</div>
                  <p className="text-xs font-black text-gray-400 uppercase tracking-widest mb-1">{card.label}</p>
                  <p className="text-xl font-black" style={{ color: card.textColor }}>{card.value}</p>
                </div>
              ))}
            </div>
            <div className="grid md:grid-cols-2 gap-6">
              <div className="bg-white rounded-3xl p-8 border border-gray-100 shadow-sm">
                <h3 className="text-xl font-black text-[#1B4332] hero-heading italic mb-6">Upcoming Appointments</h3>
                {appointments.length > 0 ? appointments.slice(0, 3).map(apt => (
                  <div key={apt.id} className="flex items-center gap-4 p-4 bg-gray-50 rounded-2xl mb-3">
                    <div className="w-10 h-10 bg-green-100 rounded-full flex items-center justify-center text-xl">≡ƒôà</div>
                    <div className="flex-1">
                      <p className="font-bold text-gray-900 text-sm">{apt.hospital}</p>
                      <p className="text-xs text-gray-400">{apt.date} at {apt.time}</p>
                    </div>
                    <span className={`px-3 py-1 rounded-full text-[10px] font-black ${apt.status === 'Confirmed' ? 'bg-green-50 text-green-600' : 'bg-yellow-50 text-yellow-600'}`}>{apt.status}</span>
                  </div>
                )) : <p className="text-gray-400 text-sm">No upcoming appointments.</p>}
              </div>
