        .typing-cursor { display: inline-block; width: 3px; height: 1em; background-color: #9FE1CB; margin-left: 4px; vertical-align: middle; animation: blink 0.7s infinite; }
        @keyframes blink { 0%,100% { opacity: 1; } 50% { opacity: 0; } }
