                    <input type="password" name="confirmPassword" required placeholder="ΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇó" className="input-field-su" value={form.confirmPassword} onChange={handleChange} />
                    <span className="field-icon-su">≡ƒ¢í∩╕Å</span>
