import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { Auth } from '../services/auth';
import { apiFetch } from '../services/api';
import '../css/styles.css';

const SupervisorPortalPage = () => {
  const navigate = useNavigate();
  const user = Auth.user;
  const [activeTab, setActiveTab] = useState('overview');
  const [toast, setToast] = useState('');
  const [beds, setBeds] = useState({ icu: { total: 0, occupied: 0 }, general: { total: 0, occupied: 0 }, emergency: { total: 0, occupied: 0 }, ot: { total: 0, occupied: 0 } });
  const [alertsSummary, setAlertsSummary] = useState(null);
  const [longStay, setLongStay] = useState([]);
  const [transfers, setTransfers] = useState([]);

  useEffect(() => {
    if (!user) { navigate('/signin'); return; }
    fetchDashboard();
  }, []);

  const fetchDashboard = async () => {
    try {
      const [dashRes, alertRes, longRes, transfersRes] = await Promise.all([
        apiFetch('/api/supervisor/dashboard/'),
        apiFetch('/api/supervisor/alerts/summary/'),
        apiFetch('/api/supervisor/long-occupancy/?days=20'),
        apiFetch('/api/patients/transfers/all/?ordering=-requested_at&status=pending'),
      ]);

      if (dashRes.ok) {
        const dash = await dashRes.json();
        const myHospitalId = user?.hospital;
        if (myHospitalId && dash.hospitals) {
          const card = dash.hospitals.find(h => h.hospital_id === String(myHospitalId));
          if (card) {
            setBeds({
              icu: { total: card.total_beds, occupied: card.occupied_beds },
              general: { total: card.total_beds, occupied: card.occupied_beds },
              emergency: { total: Math.round(card.total_beds * 0.1), occupied: Math.round(card.occupied_beds * 0.1) },
              ot: { total: Math.max(2, Math.round(card.total_beds * 0.02)), occupied: Math.round(card.occupied_beds * 0.02) },
            });
          }
        }
      }

      if (alertRes.ok) {
        setAlertsSummary(await alertRes.json());
      }

      if (longRes.ok) {
        const data = await longRes.json();
        setLongStay(data.beds || []);
      }

      if (transfersRes.ok) {
        const data = await transfersRes.json();
        setTransfers(data.results || data || []);
      }
    } catch {
      // keep defaults on error
    }
  };

  const handleLogout = async () => { await Auth.logout(); navigate('/'); };
  const showToast = (msg) => { setToast(msg); setTimeout(() => setToast(''), 3000); };

  const handleBedUpdate = (ward, field, val) => {
    setBeds(b => ({ ...b, [ward]: { ...b[ward], [field]: parseInt(val) || 0 } }));
  };

  return (
    <div style={{ fontFamily: 'Inter, sans-serif', backgroundColor: '#FDFCF7', minHeight: '100vh' }}>
      <style>{`.hero-heading { font-family: 'Playfair Display', serif; }`}</style>

      <header style={{ background: 'rgba(253,252,247,0.9)', backdropFilter: 'blur(16px)', borderBottom: '1px solid rgba(27,67,50,0.1)', position: 'fixed', top: 0, left: 0, right: 0, zIndex: 50 }}>
        <div className="max-w-7xl mx-auto px-8 py-4 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="w-9 h-9 bg-[#1B4332] rounded-xl flex items-center justify-center text-white font-bold">+</div>
            <span className="text-xl font-black text-[#1B4332]">MedGrid <span className="text-gray-400 font-medium text-sm">┬╖ Supervisor</span></span>
          </div>
          <div className="flex gap-2">
            {[['overview', '≡ƒôè Overview'], ['beds', '≡ƒ¢Å∩╕Å Bed Mgmt'], ['staff', '≡ƒæÑ Staff'], ['transfers', 'Γåö∩╕Å Transfers']].map(([id, label]) => (
              <button key={id} onClick={() => setActiveTab(id)} className={`px-4 py-2 rounded-full text-sm font-bold transition-all ${activeTab === id ? 'bg-[#1B4332] text-white' : 'text-gray-500 hover:bg-gray-100'}`}>{label}</button>
            ))}
          </div>
          <div className="flex items-center gap-3">
            <span className="text-sm font-bold text-gray-600">{user?.name || 'Supervisor'}</span>
            <button onClick={handleLogout} className="text-sm font-bold text-red-500 hover:bg-red-50 px-3 py-1.5 rounded-full">Sign Out</button>
          </div>
        </div>
      </header>

      <div className="pt-24 max-w-7xl mx-auto px-8 py-8">
        {activeTab === 'overview' && (
          <div className="space-y-8">
            <div>
              <h1 className="text-4xl font-black text-[#1B4332] hero-heading italic mb-2">Supervisor Command</h1>
              <p className="text-gray-400 font-medium">Hospital: {user?.hospitalName || 'City General Hospital'}</p>
            </div>
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
              {Object.entries(beds).map(([ward, data]) => (
                <div key={ward} className="bg-white rounded-2xl p-6 border border-gray-100 shadow-sm">
                  <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-2">{ward === 'ot' ? 'OT' : ward.charAt(0).toUpperCase() + ward.slice(1)}</p>
                  <p className="text-3xl font-black text-[#1B4332]">{data.occupied}/{data.total}</p>
                  <div className="mt-2 bg-gray-100 rounded-full h-2 overflow-hidden">
                    <div className="bg-green-500 h-full rounded-full" style={{ width: `${(data.occupied / data.total) * 100}%`, background: data.occupied / data.total > 0.9 ? '#dc2626' : data.occupied / data.total > 0.75 ? '#f59e0b' : '#16a34a' }}></div>
                  </div>
                  <p className="text-xs text-gray-400 mt-1">{data.total - data.occupied} available</p>
                </div>
              ))}
            </div>
            <div className="grid md:grid-cols-2 gap-6">
              <div className="bg-white rounded-3xl p-8 border border-gray-100 shadow-sm">
                <h3 className="text-xl font-black text-[#1B4332] italic mb-6">Alert Snapshot</h3>
                {alertsSummary ? (
                  <div className="space-y-3">
                    <div className="flex items-center justify-between">
                      <span className="text-xs font-black text-gray-400 uppercase tracking-widest">Open Alerts</span>
                      <span className="px-3 py-1 rounded-full text-[10px] font-black bg-red-50 text-red-600">{alertsSummary.total_open}</span>
                    </div>
                    <div className="grid grid-cols-3 gap-3 text-xs">
                      <div className="bg-red-50 rounded-2xl p-3">
                        <p className="font-black text-red-600 mb-1">High</p>
                        <p className="text-gray-600 text-lg font-black">{alertsSummary.high}</p>
                      </div>
                      <div className="bg-yellow-50 rounded-2xl p-3">
                        <p className="font-black text-yellow-600 mb-1">Medium</p>
                        <p className="text-gray-600 text-lg font-black">{alertsSummary.medium}</p>
                      </div>
                      <div className="bg-green-50 rounded-2xl p-3">
                        <p className="font-black text-green-600 mb-1">Low</p>
                        <p className="text-gray-600 text-lg font-black">{alertsSummary.low}</p>
                      </div>
                    </div>
                    <p className="text-[11px] text-gray-400 mt-2">
                      Resolved today: <span className="font-bold text-green-600">{alertsSummary.resolved_today}</span> ┬╖ Investigating: <span className="font-bold text-amber-600">{alertsSummary.investigating}</span>
                    </p>
                  </div>
                ) : (
                  <p className="text-gray-400 text-sm">Loading alert summary...</p>
                )}
              </div>
              <div className="bg-[#1B4332] rounded-3xl p-8 text-white">
                <h3 className="text-xl font-black italic mb-6">Quick Controls</h3>
                <div className="space-y-3">
                  {['≡ƒö┤ Mark ICU as Critical', '≡ƒôó Send All-Staff Alert', 'Γåö∩╕Å Initiate Patient Transfer', '≡ƒöÆ Lock Ward Access'].map(action => (
                    <button key={action} onClick={() => showToast(`${action} ΓÇö Executed`)} className="w-full text-left p-4 bg-white/10 rounded-2xl text-sm font-bold hover:bg-white/20 transition-all">{action}</button>
                  ))}
                </div>
              </div>
            </div>
          </div>
        )}

        {activeTab === 'beds' && (
          <div className="space-y-6">
            <div className="flex justify-between items-center">
              <h1 className="text-4xl font-black text-[#1B4332] hero-heading italic">Bed Management</h1>
              <button onClick={() => showToast('Bed data synced!')} className="bg-[#1B4332] text-white px-6 py-3 rounded-xl font-bold text-sm">Sync to Network</button>
            </div>
            <div className="grid md:grid-cols-2 gap-6">
              {Object.entries(beds).map(([ward, data]) => (
                <div key={ward} className="bg-white rounded-3xl p-8 border border-gray-100 shadow-sm">
                  <h3 className="text-xl font-black text-[#1B4332] italic mb-6">{ward === 'ot' ? 'Operating Theatre' : ward.charAt(0).toUpperCase() + ward.slice(1)} Ward</h3>
                  <div className="grid grid-cols-2 gap-4">
                    <div>
                      <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Total Beds</label>
                      <input type="number" value={data.total} onChange={e => handleBedUpdate(ward, 'total', e.target.value)} className="w-full mt-2 bg-gray-50 rounded-xl p-4 font-black text-2xl text-[#1B4332] border-none outline-none" />
                    </div>
                    <div>
                      <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Occupied</label>
                      <input type="number" value={data.occupied} onChange={e => handleBedUpdate(ward, 'occupied', e.target.value)} className="w-full mt-2 bg-gray-50 rounded-xl p-4 font-black text-2xl text-[#1B4332] border-none outline-none" />
                    </div>
                  </div>
                  <div className="mt-4 bg-gray-100 rounded-full h-3 overflow-hidden">
                    <div className="h-full rounded-full transition-all" style={{ width: `${Math.min((data.occupied / data.total) * 100, 100)}%`, background: data.occupied / data.total > 0.9 ? '#dc2626' : data.occupied / data.total > 0.75 ? '#f59e0b' : '#16a34a' }}></div>
                  </div>
                </div>
              ))}
            </div>
            <button onClick={() => showToast('Bed configuration saved and synced!')} className="w-full bg-[#1B4332] text-white py-5 rounded-2xl font-black text-lg shadow-xl hover:-translate-y-1 transition-all">Save & Sync to MedGrid Network</button>
          </div>
        )}

        {activeTab === 'staff' && (
          <div className="space-y-6">
            <h1 className="text-4xl font-black text-[#1B4332] hero-heading italic">Staff On Duty</h1>
            <div className="bg-white rounded-3xl border border-gray-100 shadow-sm overflow-hidden">
              <table className="w-full">
                <thead><tr className="border-b border-gray-50">{['Name', 'Department', 'Shift', 'Status', 'Actions'].map(h => <th key={h} className="text-left text-[10px] font-black text-gray-400 uppercase tracking-widest px-6 py-4">{h}</th>)}</tr></thead>
                <tbody>
                  <tr className="border-b border-gray-50">
                    <td className="px-6 py-6 text-center text-gray-400 text-sm" colSpan={5}>
                      Live staff on-duty data is available via `/api/hospitals/{id}/on-duty-now/`. Hook this into a dedicated staff view if needed.
                    </td>
                  </tr>
                </tbody>
              </table>
            </div>
          </div>
        )}

        {activeTab === 'transfers' && (
          <div className="space-y-6">
            <h1 className="text-4xl font-black text-[#1B4332] hero-heading italic">Transfer Requests</h1>
            <div className="space-y-4">
              {transfers.map(t => (
                <div key={t.id} className="bg-white rounded-2xl p-6 border border-gray-100 shadow-sm flex items-center gap-6">
                  <div className="w-14 h-14 bg-orange-50 rounded-2xl flex items-center justify-center text-2xl flex-shrink-0">Γåö∩╕Å</div>
                  <div className="flex-1">
                    <p className="font-black text-gray-900 text-lg">{t.patient_name}</p>
                    <p className="text-gray-500 text-sm">
                      From: {t.from_hospital_name} {t.to_hospital_name ? `ΓåÆ ${t.to_hospital_name}` : ''} ┬╖ Needs: {t.required_bed_type || 'Bed'}
                    </p>
                    <p className="text-gray-400 text-sm">{t.reason}</p>
                  </div>
                  <span className={`px-3 py-1 rounded-full text-[10px] font-black ${t.priority === 'critical' ? 'bg-red-50 text-red-600' : t.priority === 'high' ? 'bg-yellow-50 text-yellow-600' : 'bg-gray-50 text-gray-600'}`}>
                    {t.priority || 'normal'}
                  </span>
                </div>
              ))}
              {transfers.length === 0 && (
                <div className="bg-white rounded-3xl p-8 border border-gray-100 text-center text-gray-400 text-sm">
                  No pending transfers found for the selected period.
                </div>
              )}
            </div>
          </div>
        )}
      </div>
      {toast && <div className="fixed bottom-8 right-8 bg-[#1B4332] text-white px-6 py-4 rounded-2xl font-bold text-sm shadow-xl">{toast}</div>}
    </div>
  );
};

